), prepared as (
  select s.*, mod(abs(hashtext(s.slug)),4) answer_position,
    (select array_agg(fact order by ord) from (select d.fact,row_number() over(order by md5(s.slug||d.slug)) ord from seed d where d.slug<>s.slug limit 3) x) distractors
  from seed s
), rows as (
  select *, case answer_position
    when 0 then jsonb_build_array(fact,distractors[1],distractors[2],distractors[3])
    when 1 then jsonb_build_array(distractors[1],fact,distractors[2],distractors[3])
    when 2 then jsonb_build_array(distractors[1],distractors[2],fact,distractors[3])
    else jsonb_build_array(distractors[1],distractors[2],distractors[3],fact) end options
  from prepared
)
insert into public.juniors_questions(slug,subject,chapter_slug,topic,subtopic,prompt,options,correct_option,explanation,difficulty,exam_tags,status,source_reference,validated_at,validated_by,content_version)
select slug,'chemistry',chapter_slug,topic,subtopic,'Which statement correctly describes '||subtopic||'?',options,answer_position,fact,difficulty,tags,'published','NCERT Chemistry XI-XII; official JEE Main and EAPCET syllabi',now(),'codex-phase3-review','1.0'
from rows
on conflict(slug) do update set subject=excluded.subject,chapter_slug=excluded.chapter_slug,topic=excluded.topic,subtopic=excluded.subtopic,prompt=excluded.prompt,options=excluded.options,correct_option=excluded.correct_option,explanation=excluded.explanation,difficulty=excluded.difficulty,exam_tags=excluded.exam_tags,status=excluded.status,source_reference=excluded.source_reference,validated_at=excluded.validated_at,validated_by=excluded.validated_by,content_version=excluded.content_version,updated_at=now();
